      const projectPath = this.activeProject?.abs_project_path || ''
      let shortened = filePath.replace(projectPath, '').replace(/^\//, '')

      return shortened.split('/').pop()
    },

    // Extract file links from markdown content and make them clickable
    makeContentLinksClickable(content) {
      if (!content) return ''

      // Match markdown links like [text](file.md) or just file.md references
      return content.replace(/\[([^\]]+)\]\(([^)]+\.md)\)|(\w+[\w-]*\.md)/g, (match, text, url, bareFile) => {
        const fileName = url || bareFile
        if (this.isFileInModules(fileName)) {
          return `<a class="link link-primary cursor-pointer" data-file="${fileName}">${text || fileName}</a>`
        }
        return match
      })
    },

    // Check if file exists in current domain's modules
    isFileInModules(fileName) {
      if (!this.activeDomain?.files) return false
      return this.activeDomain.files.some(filePath => filePath.endsWith(fileName) || filePath.endsWith(`/${fileName}`))
    },

    // Find full path of file by its name
    findFileByName(fileName) {
      if (!this.activeDomain?.files) return null
      return this.activeDomain.files.find(filePath => 
        filePath.endsWith(fileName) || filePath.endsWith(`/${fileName}`)
      )
    },

    // Handle clicks on file links in content
    handleContentClick(event) {
      const link = event.target.closest('[data-file]')
      if (link) {
        const fileName = link.getAttribute('data-file')
        const filePath = this.findFileByName(fileName)
        if (filePath) {
          this.selectModule(filePath)
        }
      }
    }
  }
}
</script>
